#include <unistd.h>

#define TAILLE 4
#define N      60

int tampon[TAILLE];
int tete = 0, queue = 0;

sem_t mutex;
sem_t vide;
sem_t plein;

void *producteur(void *arg) {
    (void) arg;
    for (int i = 1; i <= N; i++) {
        sem_wait(&vide);                /* comptage AVANT exclusion */
        sem_wait(&mutex);
        tampon[queue] = i;
        queue = (queue + 1) % TAILLE;
        sem_post(&mutex);
        sem_post(&plein);
    }
    return NULL;
}

void *consommateur(void *arg) {
    long *somme = (long *) arg;
    for (int i = 0; i < N; i++) {
        usleep(1000);                   /* la consommation prend du temps */
        sem_wait(&plein);
        sem_wait(&mutex);
        *somme += tampon[tete];
        tete = (tete + 1) % TAILLE;
        sem_post(&mutex);
        sem_post(&vide);
    }
    return NULL;
}

int main(void) {
    pthread_t prod, cons;
    long somme = 0;

    sem_init(&mutex, 0, 1);
    sem_init(&vide, 0, TAILLE);
    sem_init(&plein, 0, 0);

    pthread_create(&prod, NULL, producteur, NULL);
    pthread_create(&cons, NULL, consommateur, &somme);

    pthread_join(prod, NULL);
    pthread_join(cons, NULL);

    sem_destroy(&mutex);
    sem_destroy(&vide);
    sem_destroy(&plein);
    printf("somme = %ld\n", somme);
    return 0;
}
